[class*='fps'], [id*='fps'], [class*='overlay'], [id*='overlay'],
[class*='panel'], [id*='panel'], [class*='toolbar'], [id*='toolbar'],
.p5-control, .ui-container, #ui, #controls, .hud, [class*='hud'],
input, button, select, textarea, label, form, nav, header {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
  width: 0 !important;
  height: 0 !important;
  position: absolute !important;
  left: -9999px !important;
  top: -9999px !important;
}
